/* H&H Field Reports demo. No backend, API key, external script, analytics or real push.
 * Project access is a UI simulation only. Never use this role switch as authentication.
 * State is local to this browser; images and edits are stored in IndexedDB.
 */
'use strict';
const ICONS={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3Z"/>',check:'<path d="m5 12 4 4L19 6"/>',checks:'<path d="m2 12 4 4L16 6m-4 10 9-10"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',file:'<path d="M14 3H5v18h14V8Zm0 0v6h5M8 13h8m-8 4h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5v2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bell:'<path d="M5 16V9a7 7 0 0 1 14 0v7l2 2H3Zm4 5h6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',arrowUp:'<path d="M6 18 18 6H6m12 0v12"/>',chev:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m14 5-7 7 7 7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h.01M13 15h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 3v4m-2-2h4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3Z"/><circle cx="12" cy="14" r="4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14ZM4 20h16"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',phone:'<path d="M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4a2 2 0 0 1-2 2A18 18 0 0 1 3 5a2 2 0 0 1 2-2Z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',repeat:'<path d="M3 7h16l-4-4m6 14H5l4 4M3 7v5m18 5v-5"/>',note:'<path d="M4 3h16v13l-5 5H4Zm11 18v-5h5M8 8h8m-8 4h5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',expand:'<path d="M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 10M20 3v5h-5"/>',leaf:'<path d="M4 20c14 1 17-9 16-17C8 2 0 9 4 20Zm0 0L15 9"/>',court:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="M12 5v14M3 9h18M3 15h18"/>',send:'<path d="m3 3 18 9-18 9 4-9Zm4 9h14"/>',home:'<path d="m3 10 9-7 9 7v11H3Zm6 11v-8h6v8"/>',logout:'<path d="M10 3H3v18h7m-1-9h12m-5-5 5 5-5 5"/>',pause:'<path d="M8 5v14m8-14v14"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=prefix=>`${prefix}-${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2,8)}`;
const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const dateLabel=(date,opts={day:'numeric',month:'short'})=>date?new Date(`${String(date).slice(0,10)}T12:00:00`).toLocaleDateString('en-SG',opts):'—';
const stamp=()=>new Date().toISOString();
const humanTime=at=>{const date=String(at).slice(0,10);return date===localISO()?'Today':date===shiftDate(-1)?'Yesterday':dateLabel(date)};
const button=(label,act,ic='',kind='',attrs='')=>`<button class="btn ${kind}" data-act="${act}" ${attrs}>${ic?icon(ic):''}${label}</button>`;
const badge=(text,color='gray',ic='')=>`<span class="badge ${color}">${ic?icon(ic):''}${esc(text)}</span>`;
const statusBadge=s=>badge({approved:'Approved',review:'Needs review',queued:'Caption needed',rejected:'Changes requested'}[s]||s,{approved:'green',review:'amber',queued:'blue',rejected:'red'}[s]||'gray');
let S,db,storageMode='Opening local workspace',persistChain=Promise.resolve(),saveTimer,storageWarned=false;
let V={role:'owner',supervisor:'s1',page:'overview',project:null,tab:'overview',query:'',filter:'all',reviewFilter:'pending',reviewProject:'all',selected:new Set(),reportProject:'p1',reportPage:0};
let pendingUploads=[],installPrompt=null,reportPreview=null,modalReturnFocus=null,uploadBusy=false,aiBusy=false;
const DB_NAME='hnh-field-reports-demo-v1';
async function initStore(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Database upgrade blocked'));});S=await new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});storageMode='Saved on this device';}catch(e){try{S=JSON.parse(localStorage.getItem(DB_NAME)||'null');storageMode='Saved on this device';}catch(_){storageMode='Session only';}}if(!S||S.schema!==1){S=makeSeed();await save();}else{S.photos.forEach(p=>{if(p.source)p.src=ASSET.photos[p.source]});S.reports.forEach(r=>r.photos?.forEach(p=>{if(p.source)p.src=ASSET.photos[p.source]}));}}
function save(){const snapshot=structuredClone(S);persistChain=persistChain.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(db){const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'workspace');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}else{try{localStorage.setItem(DB_NAME,JSON.stringify(snapshot));resolve();}catch(e){reject(e);}}})).then(()=>{storageMode='Saved on this device';const el=$('#save-status');if(el)el.textContent=storageMode;}).catch(e=>{storageMode='Session only — storage unavailable';const el=$('#save-status');if(el)el.textContent=storageMode;if(!storageWarned){storageWarned=true;toast('Device storage is unavailable or full. Your latest changes will not survive a reload.','error');}console.warn('Local save failed',e);});return persistChain;}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,350);}
const isOwner=()=>V.role==='owner';
const sup=id=>S.supervisors.find(s=>s.id===id);
const project=id=>S.projects.find(p=>p.id===id);
const canAccess=p=>!!p&&(isOwner()||(sup(V.supervisor)?.active&&p.assigned.includes(V.supervisor)));
const visibleProjects=()=>S.projects.filter(canAccess);
const projectPhotos=id=>S.photos.filter(p=>p.project===id);
const visiblePhotos=()=>S.photos.filter(p=>canAccess(project(p.project))&&(isOwner()||p.supervisor===V.supervisor));
const pendingCount=id=>S.photos.filter(p=>(!id||p.project===id)&&['queued','review','rejected'].includes(p.status)).length;
const openPrompts=id=>S.notifications.filter(n=>n.kind==='prompt'&&!n.fulfilled&&(!id||n.project===id)&&canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor));
const visibleTasks=id=>S.tasks.filter(t=>(!id||t.project===id)&&canAccess(project(t.project))&&(isOwner()||t.assigned==='all'||t.assigned===V.supervisor));
const who=()=>isOwner()?'Owner':sup(V.supervisor)?.name||'Supervisor';
function addActivity(text,pid){S.activity.unshift({id:uid('a'),project:pid,who:who(),text,at:stamp()});S.activity=S.activity.slice(0,100);}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.setAttribute('role',type==='error'?'alert':'status');el.innerHTML=icon(type==='error'?'info':'check')+`<span>${esc(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function requireOwner(){if(!isOwner()){toast('This action is available in the owner view only.','error');return false;}return true;}
const empty=(title,desc,action='',label='')=>`<div class="empty">${icon('folder')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action?button(label,action,'plus','primary'):''}</div>`;
function navItems(){return isOwner()?[['overview','grid','Overview'],['projects','folder','Projects'],['review','spark','Caption review'],['reports','file','Reports'],['team','users','Supervisors']]:[['overview','home','My workspace'],['projects','folder','My projects'],['uploads','photo','My uploads'],['tasks','checks','My tasks'],['inbox','bell','My prompts']];}
function changePage(page,pid=null){closeModal();V.page=page;V.project=pid;V.tab='overview';V.query='';V.filter='all';V.selected.clear();render();window.scrollTo({top:0,behavior:'instant'});}
function render(){if(!S)return; if(V.project&&!canAccess(project(V.project))){V.page='projects';V.project=null;}if(!isOwner()&&['review','reports','team'].includes(V.page)){V.page='overview';V.project=null;}const nav=navItems();const current=nav.find(n=>n[0]===V.page)?.[2]||(V.page==='inbox'?'Prompt activity':'Projects');const unread=S.notifications.filter(n=>!n.read&&canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).length;const name=who();
 $('#app').innerHTML=`<aside class="sidebar"><div class="brand flex"><img src="${ASSET.icon}" alt="H&H Resources emblem"><div><div class="brand-name">H&H Resources</div><small>FIELD REPORTS</small></div></div><div class="nav-label">${isOwner()?'MANAGE YOUR SITES':'ON-SITE WORKSPACE'}</div><nav aria-label="Main navigation">${nav.map(([id,ic,label])=>`<button class="nav-btn ${V.page===id?'active':''}" data-act="nav" data-page="${id}" aria-label="${label}" ${V.page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='review'&&pendingCount()?`<span class="count">${pendingCount()}</span>`:''}${id==='inbox'&&openPrompts().length?`<span class="count">${openPrompts().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-status"><strong><span class="status-dot"></span><span id="save-status">${storageMode}</span></strong>Private demo workspace<br>No data sent to a server</div><button class="nav-btn" data-act="install" aria-label="Install app">${icon('download')}<span>Install app</span></button><button class="nav-btn" data-act="help" aria-label="Demo guide">${icon('info')}<span>Demo guide</span></button><div class="profile flex"><div class="avatar dark">${isOwner()?'HH':initials(name)}</div><div><div style="font-size:12px">${esc(name)}</div><small style="font-size:10px;color:#99b09e">${isOwner()?'Owner workspace':'Supervisor · demo'}</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="mobile-brand"><img src="${ASSET.icon}" alt="">H&H <span style="font-weight:400;color:#78856e">Field Reports</span><span class="demo-tag">INTERACTIVE DEMO</span></div><div class="breadcrumb">Workspace ${icon('chev')} <strong>${V.project?'Project workspace':current}</strong></div><div class="top-actions"><span class="demo-tag">INTERACTIVE DEMO</span><div class="role-switch" role="group" aria-label="Switch demo role"><button data-act="role" data-role="owner" class="${isOwner()?'active':''}" aria-pressed="${isOwner()}">${icon('shield')}Owner</button><button data-act="role" data-role="supervisor" class="${!isOwner()?'active':''}" aria-pressed="${!isOwner()}">${icon('user')}Supervisor</button></div>${!isOwner()?`<select id="identity" aria-label="Supervisor identity">${S.supervisors.filter(s=>s.active).map(s=>`<option value="${s.id}" ${V.supervisor===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}<button class="icon-btn" data-act="inbox" aria-label="Open prompts and notifications">${icon('bell')}${unread?'<span class="notif-dot"></span>':''}</button><button class="icon-btn" data-act="help" aria-label="Demo guide">${icon('info')}</button></div></header><main class="main" id="main">${renderPage()}<div class="footer-note"><span>H&H Resources · Field Reports<br>Demo data · AI & reminders are simulated · Local storage only</span><button class="text-btn" data-act="help">How this demo works ${icon('arrowUp')}</button></div></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav.map(([id,ic,label])=>`<button data-act="nav" data-page="${id}" class="${V.page===id?'active':''}" ${V.page===id?'aria-current="page"':''}>${icon(ic)}<span>${({'overview':isOwner()?'Overview':'Home','projects':'Projects','review':'Review','reports':'Reports','team':'Team','uploads':'Uploads','tasks':'Tasks','inbox':'Prompts'})[id]}</span>${id==='review'&&pendingCount()?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav>`;
 if(V.page==='reports'&&V.tab!=='history')setTimeout(refreshReportPreview,30);
}
function renderPage(){if(V.project)return renderProject();if(V.page==='overview')return isOwner()?ownerDashboard():supervisorDashboard();if(V.page==='projects')return projectsPage();if(V.page==='review')return reviewPage();if(V.page==='team')return teamPage();if(V.page==='reports')return reportsPage();if(V.page==='uploads')return uploadsPage();if(V.page==='tasks')return tasksPage();if(V.page==='inbox')return inboxPage();return ownerDashboard();}
function metric(title,num,sub,ic,action=''){return `<div class="metric"><div class="metric-head">${icon(ic)}${title}</div><div class="metric-number mono">${num}</div><div class="metric-sub">${sub}</div>${action?`<button class="metric-link" data-act="nav" data-page="${action}" aria-label="View ${title}">${icon('arrowUp')}</button>`:''}</div>`;}
function flow(){return `<div class="work-flow"><span class="flow-step active">${icon('camera')}Capture</span>${icon('chev')}<span class="flow-step">${icon('spark')}AI draft</span>${icon('chev')}<span class="flow-step">${icon('shield')}Owner review</span>${icon('chev')}<span class="flow-step">${icon('file')}Export PDF</span></div>`;}
function ownerDashboard(){const active=S.projects.filter(p=>p.status==='Active');const feature=project('p1')||S.projects[0];const due=visibleTasks().filter(t=>!t.done&&t.type==='task').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);const pending=S.photos.filter(p=>p.status==='review').slice(-4);return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">YOUR SITES, IN FOCUS</div><h1>Project overview</h1><p>From the first site photo to a client-ready progress report.</p></div>${button('New project','project-new','plus','primary')}</div><div class="metrics">${metric('Active projects',active.length,'Across your workspace','folder','projects')}${metric('Awaiting review',pendingCount(),`${S.photos.filter(p=>p.status==='queued').length} still need a caption`,'spark','review')}${metric('Photo updates due',new Set(openPrompts().map(n=>n.project+':'+n.to)).size,'Open supervisor prompts','clock')}${metric('Active supervisors',S.supervisors.filter(s=>s.active).length,'Assigned access only','users','team')}</div><div class="dashboard-grid"><div class="stack"><div>${feature?`<article class="featured">${feature.hero?`<img src="${ASSET.photos[feature.hero]}" alt="School field from the supplied SACPS report">`:''}<span class="glass-badge">${esc(feature.status)} project · Demo schedule</span><div class="featured-content"><div class="eyebrow">FEATURED PROJECT · ${esc(feature.code)}</div><h2>${esc(feature.name)}</h2><p>${esc(feature.category)} &nbsp;·&nbsp; ${feature.assigned.length} supervisors assigned</p><div class="flex between wrap">${button('Open project','project-open','arrow','lime',`data-id="${feature.id}"`)}<span class="feature-meta">${icon('calendar')} Target ${dateLabel(feature.end)}</span></div></div></article>`:empty('Your first project starts here','Set a timeline, assign supervisors and define the photo-reporting schedule.','project-new','Create project')}${flow()}</div><section><div class="section-heading"><h2>Projects at a glance</h2><button class="text-btn" data-act="nav" data-page="projects">View all ${icon('arrow')}</button></div><div class="panel table-wrap">${projectsTable(S.projects.slice(0,4))}</div></section><section class="panel"><div class="panel-head"><h3>Latest activity</h3><span class="eyebrow" style="font-size:8px">WORKSPACE RECORD</span></div><div class="panel-body">${activityRows(S.activity.slice(0,3))}</div></section></div><div class="dashboard-secondary"><section class="panel"><div class="panel-head"><h3>Needs your attention</h3>${badge(`${pendingCount()} photos`,'amber')}</div><div class="panel-body"><p class="small muted" style="font-size:11px;line-height:1.8">Review picture captions together, make any edits, then approve them for your report.</p><div class="review-teaser">${pending.map(p=>`<img src="${p.src}" alt="${esc(p.title)}">`).join('')}</div>${button('Review photo captions','nav','spark','primary','data-page="review" style="width:100%"')}<p class="small muted" style="font-size:9px;margin-top:10px;text-align:center">Only owner-approved captions enter a final PDF.</p></div></section><section class="panel mt"><div class="panel-head"><h3>Upcoming site tasks</h3>${icon('calendar')}</div><div class="panel-body">${due.length?due.map(t=>`<div class="next-card"><div class="date-chip"><b>${new Date(t.due+'T12:00:00').getDate()}</b><small>${dateLabel(t.due,{month:'short'})}</small></div><div class="grow"><h4>${esc(t.text)}</h4><p>${esc(project(t.project)?.code)} · ${esc(sup(t.assigned)?.name||'All supervisors')}</p>${badge(t.due<=localISO()?'Due today':dateLabel(t.due),t.due<=localISO()?'amber':'gray')}</div></div>`).join(''):'<p class="small muted">No open site tasks.</p>'}</div></section><div class="quiet mt"><div class="flex" style="gap:8px;margin-bottom:7px">${icon('shield')}<strong style="font-size:11px">Human-reviewed, before it leaves.</strong></div><p style="font-size:10px;line-height:1.8">AI drafts the commentary. You verify the facts. Approved photos become a clear, numbered progress report.</p></div></div></div>`;}
function projectsTable(projects){if(!projects.length)return empty('No projects yet','Create your first project to start collecting progress photos.');return `<table class="project-table"><thead><tr><th>Project</th><th>Photo review</th><th>Team</th><th></th></tr></thead><tbody>${projects.map(p=>{const all=projectPhotos(p.id),approved=all.filter(x=>x.status==='approved').length;return `<tr><td><div class="flex" style="gap:10px"><div class="project-symbol">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="">`:icon(p.category.includes('Landscape')?'leaf':'court')}</div><div><button class="project-title" data-act="project-open" data-id="${p.id}">${esc(p.name)}</button><div class="muted" style="font-size:9px;margin-top:3px">${esc(p.code)} &nbsp;·&nbsp; ${esc(p.status)}</div></div></div></td><td><div class="progress-cell"><div class="progress-label"><span>${approved}/${all.length} approved</span></div><div class="bar"><span style="width:${all.length?approved/all.length*100:0}%"></span></div></div></td><td><div class="avatars">${p.assigned.map(id=>`<span class="avatar" title="${esc(sup(id)?.name)}">${initials(sup(id)?.name)}</span>`).join('')}</div></td><td><button class="icon-btn" data-act="project-open" data-id="${p.id}" aria-label="Open ${esc(p.name)}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table>`;}
function activityRows(rows){return rows.length?rows.map(a=>`<div class="activity-row"><span class="avatar">${initials(a.who)}</span><div class="grow"><p><strong>${esc(a.who)}</strong> ${esc(a.text)}</p><small>${esc(project(a.project)?.code||'Workspace')} · ${humanTime(a.at)}</small></div></div>`).join(''):'<p class="small muted">Activity will appear as you use the demo.</p>';}
function projectCard(p){const photos=projectPhotos(p.id).filter(x=>isOwner()||x.supervisor===V.supervisor);const approved=photos.filter(x=>x.status==='approved').length;const prompts=openPrompts(p.id);return `<article class="project-card"><div class="project-card-cover">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="SACPS field from supplied report">`:`<div class="plan-art ${p.category.includes('Landscape')?'landscape':''}">${icon(p.category.includes('Landscape')?'leaf':'court')}</div>`}${badge(p.status,p.status==='Active'?'green':'gray')}</div><div class="project-card-body"><div class="eyebrow" style="font-size:8px;margin-bottom:8px">${esc(p.code)} · ${esc(p.category)}</div><h3>${esc(p.name)}</h3><p>${icon('calendar')} ${dateLabel(p.start)} — ${dateLabel(p.end)}</p><div class="flex between" style="margin:19px 0 8px"><span class="small muted" style="font-size:10px">${isOwner()?'Report approval':'My submissions'}</span><span class="small" style="font-size:10px">${approved}/${photos.length} photos approved</span></div><div class="bar"><span style="width:${photos.length?approved/photos.length*100:0}%"></span></div><div class="card-footer"><div class="avatars">${p.assigned.map(id=>`<span class="avatar" title="${esc(sup(id)?.name)}">${initials(sup(id)?.name)}</span>`).join('')}</div>${!isOwner()&&prompts.length?badge('Photo update due','amber'):''}${button('Open project','project-open','arrow','sm',`data-id="${p.id}"`)}</div></div></article>`;}
function projectsPage(){const rows=visibleProjects().filter(p=>(V.filter==='all'||p.status===V.filter)&&`${p.name} ${p.code} ${p.category}`.toLowerCase().includes(V.query.toLowerCase()));return `<div class="page-heading"><div><h1>${isOwner()?'Projects':'My projects'}</h1><p>${isOwner()?'Set the brief. Keep every worksite moving.':'Only projects assigned to you are shown here.'}</p></div>${isOwner()?button('New project','project-new','plus','primary'):''}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search projects…" aria-label="Search projects"></label><select id="project-filter" aria-label="Project status"><option value="all">All statuses</option>${['Active','On hold','Completed'].map(s=>`<option ${V.filter===s?'selected':''}>${s}</option>`).join('')}</select></div>${rows.length?`<div class="cards-grid">${rows.map(projectCard).join('')}</div>`:empty('No matching projects',isOwner()?'Create a project or try another search.':'Ask the owner to assign you to a project.')}`;}
function supervisorDashboard(){const ps=visibleProjects(),prompts=openPrompts(),tasks=visibleTasks().filter(t=>t.type==='task'&&!t.done);return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">SUPERVISOR WORKSPACE</div><h1>Hello, ${esc(who().split(' ')[0])}.</h1><p>Keep your site updates clear, current and in one place.</p></div>${button('Upload photos','upload-open','camera','primary')}</div><section class="supervisor-welcome"><div class="grow"><div class="eyebrow">${prompts.length?'YOUR NEXT UPDATE':'READY WHEN YOU ARE'}</div><h2>${prompts.length?'A few photos. A clear update.':'Show the progress on your site.'}</h2><p>${prompts.length?`You have ${prompts.length} open photo prompt${prompts.length!==1?'s':''}. Add your site photos and a short note — the owner will review the captions.`:'Open an assigned project, capture the work stage and send photos for owner review.'}</p>${button('View my prompts','nav','bell','','data-page="inbox" style="margin-top:17px"')}</div>${icon('camera')}</section><div class="metrics">${metric('Assigned projects',ps.length,'Your workspaces only','folder','projects')}${metric('Photo prompts',prompts.length,'Awaiting your update','bell','inbox')}${metric('My photos',visiblePhotos().length,'Submitted to the owner','photo','uploads')}${metric('Open tasks',tasks.length,'Owner instructions','checks','tasks')}</div><div class="section-heading"><h2>Your assigned sites</h2><span class="small muted">${ps.length} project${ps.length!==1?'s':''}</span></div>${ps.length?`<div class="cards-grid">${ps.map(projectCard).join('')}</div>`:empty('No assigned projects','Switch to the owner view and tag this supervisor to a project.')}<div class="panel mt"><div class="panel-head"><h3>Tasks & owner remarks</h3><button class="text-btn" data-act="nav" data-page="tasks">View all ${icon('arrow')}</button></div><div class="panel-body">${tasks.slice(0,3).map(renderTask).join('')||'<p class="small muted">No open tasks right now.</p>'}</div></div>`;}
function renderProject(){const p=project(V.project);const ph=visiblePhotos().filter(x=>x.project===p.id);const ts=visibleTasks(p.id);const tabs=isOwner()?[['overview','Overview'],['photos',`Photos (${ph.length})`],['tasks',`Tasks & remarks (${ts.length})`],['schedule','Timeline & prompts']]:[['overview','Overview'],['photos',`My photos (${ph.length})`],['tasks',`Tasks & remarks (${ts.length})`]];return `<div class="flex between mb"><button class="text-btn" data-act="nav" data-page="projects">${icon('left')} All ${isOwner()?'':'my '}projects</button>${isOwner()?button('Edit project','project-edit','edit','sm',`data-id="${p.id}"`):badge('Assigned access','green','shield')}</div><section class="project-detail-banner">${p.hero?`<img src="${ASSET.photos[p.hero]}" alt="SACPS field overview">`:`<div class="plan-art">${icon('court')}</div>`}<div class="grow"><div class="flex wrap" style="gap:8px"><span class="eyebrow" style="font-size:8px">${esc(p.code)}</span>${badge(p.status,p.status==='Active'?'green':'gray')}</div><h1>${esc(p.name)}</h1><div class="flex wrap small muted" style="font-size:11px;gap:10px"><span>${esc(p.category)}</span><span>· ${esc(p.location)}</span></div></div><div class="flex">${isOwner()?button('Review captions','project-review','spark','primary',`data-id="${p.id}"`):button('Upload photos','upload-open','camera','primary',`data-id="${p.id}"`)}</div></section><div class="tabs" role="tablist">${tabs.map(([id,label])=>`<button class="tab ${V.tab===id?'active':''}" role="tab" aria-selected="${V.tab===id}" data-act="tab" data-tab="${id}">${label}</button>`).join('')}</div>${V.tab==='overview'?projectOverview(p):V.tab==='photos'?`<div class="section-heading"><div><h2>${isOwner()?'Project photo record':'My submitted photos'}</h2><p class="small muted" style="font-size:10px;margin-top:5px">Click a photograph to view it uncropped.</p></div>${isOwner()?button('Create report','project-report','file','',`data-id="${p.id}"`):button('Upload photos','upload-open','plus','primary',`data-id="${p.id}"`)}</div>${ph.length?`<div class="photo-grid">${ph.slice().reverse().map(photoTile).join('')}</div>`:empty('No photos yet','Switch to a tagged supervisor and upload site-progress photos.')}`:V.tab==='tasks'?`<div class="section-heading"><div><h2>Site instructions</h2><p class="small muted" style="font-size:11px;margin-top:5px">Add tasks or remarks throughout the project, including recurring instructions.</p></div>${isOwner()?button('Add task / remark','task-new','plus','primary',`data-id="${p.id}"`):''}</div><div class="panel"><div class="panel-body" style="padding-top:5px">${ts.length?ts.map(renderTask).join(''):empty('No tasks yet','The owner can add tasks and remarks at any time.')}</div></div>`:projectSchedule(p)}`;}
function projectOverview(p){const photos=projectPhotos(p.id),approved=photos.filter(x=>x.status==='approved').length;return `<div class="split"><div class="stack"><section class="panel"><div class="panel-head"><h3>Project brief</h3>${badge('Caption context','green','spark')}</div><div class="panel-body"><p class="description">${esc(p.description)}</p>${isOwner()?`<div class="divider"></div><div class="eyebrow" style="font-size:9px;margin-bottom:8px">CAPTION WRITING INSTRUCTIONS</div><p class="small muted" style="line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere">${esc(p.aiInstructions)}</p>`:''}</div></section><section class="panel"><div class="panel-head"><h3>Tasks & owner remarks</h3>${isOwner()?button('Add','task-new','plus','sm',`data-id="${p.id}"`):''}</div><div class="panel-body">${visibleTasks(p.id).filter(t=>!t.done).slice(0,4).map(renderTask).join('')||'<p class="small muted">No open tasks or remarks.</p>'}</div></section><section class="panel"><div class="panel-head"><h3>Recent activity</h3></div><div class="panel-body">${activityRows(S.activity.filter(a=>a.project===p.id).slice(0,4))}</div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h3>Project timeline</h3>${icon('calendar')}</div><div class="panel-body"><div class="date-timeline"><div><small>Start date</small><b>${dateLabel(p.start)}</b></div><div class="timeline-track"></div><div><small>Target date</small><b>${dateLabel(p.end)}</b></div></div><div class="notice" style="margin-bottom:0">${icon('info')}<span>Dates represent the project window, not a certified completion percentage.</span></div></div></section><section class="panel"><div class="panel-head"><h3>Photo update schedule</h3>${icon('clock')}</div><div class="panel-body"><h2 style="font-size:22px;margin:3px 0 4px">${cadenceLabel(p)}</h2><p class="small muted">${formatTime(p.time)} · ${p.minimum} photos per update</p><p class="small muted" style="margin-top:12px;font-size:10px">Next scheduled prompt<br><strong style="color:#4a6541;font-weight:550">${nextPromptLabel(p)}</strong></p>${isOwner()?button('Prompt supervisors now','prompt-now','bell','','style="width:100%;margin-top:17px" data-id="'+p.id+'"'):button('Submit photo update','upload-open','camera','primary','style="width:100%;margin-top:17px" data-id="'+p.id+'"')}<p class="small muted" style="font-size:9px;margin-top:9px">In-app simulation. No messages are sent externally.</p></div></section>${isOwner()?`<section class="panel"><div class="panel-head"><h3>Report readiness</h3></div><div class="panel-body"><div class="flex between mb"><span style="font-size:27px;font-weight:600">${approved}<span class="muted" style="font-size:15px"> / ${photos.length}</span></span><span class="small muted">photos approved</span></div><div class="bar"><span style="width:${photos.length?approved/photos.length*100:0}%"></span></div>${button('Prepare progress report','project-report','file','','style="width:100%;margin-top:17px" data-id="'+p.id+'"')}</div></section>`:''}<section class="panel"><div class="panel-head"><h3>Assigned supervisors</h3></div><div class="panel-body">${p.assigned.map(id=>`<div class="flex" style="margin:10px 0"><span class="avatar">${initials(sup(id)?.name)}</span><div><div style="font-size:12px">${esc(sup(id)?.name||'Removed supervisor')}</div><small class="muted" style="font-size:10px">${sup(id)?.active?'Active supervisor':'Inactive'}</small></div></div>`).join('')||'<p class="small muted">No supervisors assigned.</p>'}</div></section></div></div>`;}
function cadenceLabel(p){return {daily:'Every day',weekdays:'Weekdays',weekly:'Every '+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][p.weekday],interval:`Every ${p.interval} days`}[p.cadence]||'Every day';}
function formatTime(t){const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`;}
function nextPrompt(p){if(p.status!=='Active')return null;const now=new Date();for(let i=0;i<500;i++){const d=new Date(`${shiftDate(i)}T${p.time}:00`),date=localISO(d);if(date<p.start||d<=now)continue;if(date>p.end)return null;const dow=d.getDay();if(p.cadence==='weekdays'&&(dow===0||dow===6))continue;if(p.cadence==='weekly'&&dow!==Number(p.weekday))continue;if(p.cadence==='interval'){const day=Math.round((new Date(date+'T12:00:00')-new Date(p.start+'T12:00:00'))/86400000);if(day%Number(p.interval)!==0)continue;}return d;}return null;}
function nextPromptLabel(p){const d=nextPrompt(p);return d?`${dateLabel(localISO(d),{weekday:'short',day:'numeric',month:'short'})} at ${formatTime(p.time)}`:'No upcoming prompt in this project window';}
function projectSchedule(p){const ns=S.notifications.filter(n=>n.project===p.id&&n.kind==='prompt').slice().reverse();return `<div class="split"><section class="panel"><div class="panel-head"><h3>Timeline & recurring photo prompts</h3>${button('Edit settings','project-edit','edit','sm',`data-id="${p.id}"`)}</div><div class="panel-body"><dl class="info-grid"><div><dt>Project start</dt><dd>${dateLabel(p.start,{day:'numeric',month:'long',year:'numeric'})}</dd></div><div><dt>Target completion</dt><dd>${dateLabel(p.end,{day:'numeric',month:'long',year:'numeric'})}</dd></div><div><dt>Photo prompt frequency</dt><dd>${cadenceLabel(p)}</dd></div><div><dt>Time · device local timezone</dt><dd>${formatTime(p.time)}</dd></div><div><dt>Minimum photos per update</dt><dd>${p.minimum}</dd></div><div><dt>Recipients</dt><dd>${p.assigned.map(id=>esc(sup(id)?.name||'Removed')).join(', ')||'None'}</dd></div></dl><div class="divider"></div><p class="small muted">Next scheduled prompt</p><h3 style="margin:6px 0 19px">${nextPromptLabel(p)}</h3><div class="notice amber">${icon('info')}<span>The schedule is calculated locally. This demo does not run background jobs or send WhatsApp, email or push notifications. The button below creates a prompt in each assigned supervisor’s demo inbox.</span></div>${button('Simulate scheduled prompt','prompt-simulate','repeat','primary',`data-id="${p.id}" ${nextPrompt(p)?'':'disabled'}`)}</div></section><section class="panel"><div class="panel-head"><h3>Prompt history</h3>${button('Prompt now','prompt-now','bell','sm',`data-id="${p.id}"`)}</div><div class="panel-body">${ns.length?ns.map(n=>`<div class="notification"><span class="avatar">${icon('bell')}</span><div class="grow"><p><strong>${esc(sup(n.to)?.name||'Removed supervisor')}</strong></p><p class="small muted" style="font-size:11px;margin:4px 0 7px">${esc(n.text)}</p>${badge(n.fulfilled?'Photo update submitted':'Awaiting update',n.fulfilled?'green':'amber')}<div><small>${humanTime(n.created)} · In-app demo</small></div></div></div>`).join(''):'<p class="small muted">No prompts sent yet.</p>'}</div></section></div>`;}
function renderTask(t){const p=project(t.project);const due=t.due<localISO()?'Overdue':t.due===localISO()?'Due today':dateLabel(t.due);return `<div class="task ${t.done?'done':''} ${t.type==='remark'?'task-note':''}">${t.type==='remark'?icon('note'):`<button class="check-task ${t.done?'done':''}" data-act="task-toggle" data-id="${t.id}" aria-label="${t.done?'Reopen':'Complete'} task: ${esc(t.text)}">${t.done?icon('check'):''}</button>`}<div class="grow"><div class="task-title">${esc(t.text)}</div><div class="task-meta"><span>${esc(p?.code)}</span><span>· ${esc(t.assigned==='all'?'All supervisors':sup(t.assigned)?.name||'Unassigned')}</span>${!t.done?badge(due,t.due<=localISO()?'amber':'gray'):badge('Completed','green')}${t.repeat!=='none'?badge(`${t.repeat==='daily'?'Daily':'Weekly'} ${t.type}`,'gray','repeat'):''}${t.priority==='High'&&!t.done?badge('High priority','red'):''}</div></div>${isOwner()?`<div class="task-actions"><button class="icon-btn" data-act="task-edit" data-id="${t.id}" aria-label="Edit instruction">${icon('edit')}</button><button class="icon-btn" data-act="task-delete" data-id="${t.id}" aria-label="Delete instruction">${icon('trash')}</button></div>`:''}</div>`;}
function tasksPage(){const ts=visibleTasks().sort((a,b)=>Number(a.done)-Number(b.done)||a.due.localeCompare(b.due));return `<div class="page-heading"><div><h1>My tasks & remarks</h1><p>Site instructions from the owner, across your assigned projects.</p></div></div><div class="notice">${icon('repeat')}<span>Completing a recurring task schedules its next occurrence. Remarks remain visible as reference instructions.</span></div><section class="panel"><div class="panel-body" style="padding-top:8px">${ts.length?ts.map(renderTask).join(''):empty('All clear','There are no instructions for you yet.')}</div></section>`;}
function photoTile(p){return `<article class="photo-tile"><button class="photo-image" data-act="photo-open" data-id="${p.id}" aria-label="View ${esc(p.title)}"><img src="${p.src}" loading="lazy" alt="${esc(p.title)}">${statusBadge(p.status)}</button><div class="photo-body"><span class="eyebrow" style="font-size:8px;letter-spacing:.5px">${esc(project(p.project)?.code)} · ${dateLabel(p.date)}</span><h4>${esc(p.title)}</h4><p>${esc(sup(p.supervisor)?.name||'Former supervisor')}</p>${p.status==='rejected'?`<p class="caption" style="color:var(--danger)">Owner’s note: ${esc(p.rejection||'Please provide more context.')}</p>`:''}${!isOwner()&&p.supervisor===V.supervisor&&p.status==='rejected'?button('Add clarification','photo-clarify','edit','sm','data-id="'+p.id+'" style="margin-top:9px"'):''}</div></article>`;}
function uploadsPage(){let ph=visiblePhotos().filter(p=>`${p.title} ${p.note} ${project(p.project)?.name}`.toLowerCase().includes(V.query.toLowerCase())&&(V.filter==='all'||p.status===V.filter)).reverse();return `<div class="page-heading"><div><h1>My photo uploads</h1><p>Your submissions and the owner’s review status.</p></div>${button('Upload photos','upload-open','camera','primary')}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search my photos…" aria-label="Search photos"></label><select id="photo-filter" aria-label="Photo status"><option value="all">All statuses</option>${[['review','Needs review'],['approved','Approved'],['queued','Caption needed'],['rejected','Changes requested']].map(([k,s])=>`<option value="${k}" ${V.filter===k?'selected':''}>${s}</option>`).join('')}</select></div>${ph.length?`<div class="photo-grid">${ph.map(photoTile).join('')}</div>`:empty('No matching uploads','Choose an assigned project and submit your first photo update.','upload-open','Upload photos')}`;}
function reviewRows(){return S.photos.filter(p=>(V.reviewProject==='all'||p.project===V.reviewProject)&&({pending:['review','queued','rejected'],review:['review'],approved:['approved'],queued:['queued'],rejected:['rejected'],all:['review','queued','approved','rejected']}[V.reviewFilter]||[]).includes(p.status)&&`${p.title} ${p.caption} ${project(p.project)?.name}`.toLowerCase().includes(V.query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id,undefined,{numeric:true}));}
function reviewPage(){const rows=reviewRows();const queued=rows.filter(p=>p.status==='queued').length;return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:8px">YOU HAVE THE FINAL SAY</div><h1>Photo caption review</h1><p>Review every picture, refine the commentary, approve together.</p></div>${button('Generate missing','generate-missing','spark','primary',queued?'':'disabled')}</div><div class="notice">${icon('spark')}<span><strong>AI demonstration.</strong> Sample captions use the supplied report. For new uploads, contextual draft templates use the project brief, selected work stage and your notes — not real image recognition. Verify every statement before approval.</span></div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search photo captions…" aria-label="Search captions"></label><select id="review-project" aria-label="Review project"><option value="all">All projects</option>${S.projects.map(p=>`<option value="${p.id}" ${V.reviewProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="review-status" aria-label="Review status">${[['pending','All pending'],['review','Ready to review'],['queued','Caption needed'],['rejected','Changes requested'],['approved','Approved'],['all','All photos']].map(([id,label])=>`<option value="${id}" ${V.reviewFilter===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="section-heading"><span class="small muted">${rows.length} photo${rows.length!==1?'s':''} in this view</span><span class="small muted" style="font-size:10px">Edits save automatically · Image date = demo submission date</span></div>${rows.length?`<div class="review-grid">${rows.map(reviewCard).join('')}</div><div class="bulkbar"><label><input type="checkbox" id="select-all" ${rows.filter(p=>p.status==='review').length>0&&rows.filter(p=>p.status==='review').every(p=>V.selected.has(p.id))?'checked':''}> Select review-ready photos</label><div class="flex"><span class="small" style="font-size:10px" id="selected-count">${V.selected.size} selected</span>${button('Approve selected','approve-selected','checks','lime',V.selected.size?'':'disabled')}${button('Approve all visible','approve-all','check','ghost',rows.some(p=>p.status==='review')?'':'disabled')}</div></div>`:empty('You’re all caught up','No photos match this filter. Approved photos are ready in the report builder.')}`;}
function reviewCard(p){return `<article class="review-card ${V.selected.has(p.id)?'selected':''}" data-card="${p.id}"><div class="review-card-top"><label class="flex" style="gap:8px"><input type="checkbox" data-select="${p.id}" ${V.selected.has(p.id)?'checked':''} ${p.status==='review'?'':'disabled'} aria-label="Select ${esc(p.title)}"><span>${esc(project(p.project)?.code)} · ${p.source?'Photo '+String(p.source).padStart(2,'0'):'New upload'}</span></label><span data-status="${p.id}">${statusBadge(p.status)}</span></div><div class="review-image"><img src="${p.src}" alt="${esc(p.title)}" loading="lazy"><button class="icon-btn" data-act="photo-open" data-id="${p.id}" aria-label="Expand photo">${icon('expand')}</button></div><div class="review-body"><div class="flex between wrap" style="gap:6px"><h3>${esc(p.title)}</h3><span class="small muted" style="font-size:9px">${dateLabel(p.date)} · ${esc(sup(p.supervisor)?.name||'Former supervisor')}</span></div><p class="small muted" style="font-size:10px;line-height:1.65;overflow-wrap:anywhere">Site note: ${esc(p.note||'No note supplied.')}</p><div class="eyebrow">${p.status==='queued'?'CAPTION NOT GENERATED':'EDITABLE PHOTO COMMENTARY'}</div><textarea data-caption="${p.id}" maxlength="420" placeholder="${p.status==='queued'?'Generate a draft, or write your own factual caption.':'Write a factual picture description…'}" aria-label="Caption for ${esc(p.title)}">${esc(p.caption)}</textarea>${p.status==='rejected'?`<p class="small" style="font-size:10px;color:var(--danger);margin-top:5px">Changes requested: ${esc(p.rejection)}</p>`:''}</div><div class="review-card-footer"><button class="text-btn" data-act="regenerate" data-id="${p.id}" style="font-size:10px">${icon('spark')}${p.status==='queued'?'Generate draft':'Regenerate'}</button><div class="flex" style="gap:5px">${p.status!=='approved'?button('Request changes','request-changes','','ghost sm',`data-id="${p.id}"`):''}${button(p.status==='approved'?'Approved':'Approve','approve-one','check',p.status==='approved'?'sm':'sm primary',`data-id="${p.id}" ${p.status==='approved'||!p.caption.trim()?'disabled':''}`)}</div></div></article>`;}
function teamPage(){const rows=S.supervisors.filter(s=>`${s.name} ${s.email}`.toLowerCase().includes(V.query.toLowerCase())&&(V.filter==='all'||(V.filter==='active'?s.active:!s.active)));return `<div class="page-heading"><div><h1>Supervisors</h1><p>Manage your field team and exactly which projects they can access.</p></div>${button('Add supervisor','supervisor-new','plus','primary')}</div><div class="filterbar"><label class="search">${icon('search')}<input id="search" value="${esc(V.query)}" placeholder="Search your team…" aria-label="Search supervisors"></label><select id="team-filter" aria-label="Supervisor status">${[['all','All supervisors'],['active','Active only'],['inactive','Inactive only']].map(([v,s])=>`<option value="${v}" ${V.filter===v?'selected':''}>${s}</option>`).join('')}</select></div><div class="notice">${icon('shield')}<span>Supervisor project access is controlled by assignments. Deactivation removes the supervisor from the demo role selector, while preserving their photos. All initial names and contact details are fictional.</span></div>${rows.length?`<div class="cards-grid">${rows.map(s=>{const ps=S.projects.filter(p=>p.assigned.includes(s.id));return `<article class="team-card"><div class="flex between"><span class="avatar">${initials(s.name)}</span>${badge(s.active?'Active':'Inactive',s.active?'green':'gray')}</div><h3>${esc(s.name)}</h3><p class="small muted" style="font-size:10px">Site supervisor</p><div class="team-details"><span class="flex" style="gap:8px">${icon('mail')}<span class="truncate">${esc(s.email)}</span></span><span class="flex" style="gap:8px">${icon('phone')}${esc(s.phone||'No phone number')}</span></div><div class="eyebrow" style="font-size:8px;margin-bottom:9px">ASSIGNED PROJECTS · ${ps.length}</div><div class="assignment-tags">${ps.length?ps.map(p=>badge(p.code,'gray')).join(''):badge('No assignments','gray')}</div><div class="card-footer">${button('Edit supervisor','supervisor-edit','edit','sm',`data-id="${s.id}"`)}<div class="flex" style="gap:5px"><button class="icon-btn" data-act="supervisor-toggle" data-id="${s.id}" aria-label="${s.active?'Deactivate':'Activate'} ${esc(s.name)}">${icon(s.active?'pause':'check')}</button><button class="icon-btn" data-act="supervisor-delete" data-id="${s.id}" aria-label="Delete ${esc(s.name)}">${icon('trash')}</button></div></div></article>`;}).join('')}</div>`:empty('No matching supervisors','Add a supervisor or adjust the search.','supervisor-new','Add supervisor')}`;}
function inboxPage(){const ns=S.notifications.filter(n=>canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).slice().reverse();return `<div class="page-heading"><div><h1>${isOwner()?'Prompt activity':'My photo prompts'}</h1><p>${isOwner()?'The owner’s view of in-app supervisor prompts.':'Photo reminders for your assigned projects.'}</p></div>${button('Mark all read','notifications-read','checks','')}</div><div class="notice amber">${icon('bell')}<span>Demo inbox only. No real email, WhatsApp or device push notifications are sent.</span></div><section class="panel"><div class="panel-body" style="padding-top:6px">${ns.length?ns.map(n=>`<div class="notification"><span class="avatar">${icon('bell')}</span><div class="grow"><div class="flex between wrap"><h3 style="font-size:13px">${esc(project(n.project)?.name)}</h3>${badge(n.fulfilled?'Submitted':n.kind==='prompt'?'Photos requested':'Owner update',n.fulfilled?'green':'amber')}</div><p style="margin:7px 0">${esc(n.text)}</p><small>${humanTime(n.created)} ${isOwner()?'· '+esc(sup(n.to)?.name||'Former supervisor'):''} ${n.read?'':'· Unread'}</small>${!isOwner()&&!n.fulfilled?`<div style="margin-top:11px">${n.kind==='clarification'&&n.photo?button('Clarify photo','photo-clarify','edit','sm primary',`data-id="${n.photo}"`):button('Upload photos','upload-open','camera','sm primary',`data-id="${n.project}"`)}</div>`:''}</div></div>`).join(''):empty('No prompts yet','When the owner sends a photo prompt, it will appear here.')}</div></section>`;}
let confirmCallback=null;
function openModal(title,subtitle,body,footer='',size=''){modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${size}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-act="modal-close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>{const f=$('.modal input:not([type=hidden])')||$('.modal select')||$('.modal button');f?.focus();},60);}
function closeModal(){if(uploadBusy)return;$('#modal-root').innerHTML='';document.body.style.overflow='';confirmCallback=null;pendingUploads=[];modalReturnFocus?.isConnected&&modalReturnFocus.focus();}
function confirmDialog(title,message,callback,label='Confirm',danger=false){openModal(title,'',`<p class="description" style="font-size:13px">${esc(message)}</p>`,button('Cancel','modal-close','','')+button(label,'confirm-action',danger?'trash':'check',danger?'danger':'primary'),'narrow');confirmCallback=callback;}
function formField(label,name,value='',type='text',extra='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function supervisorChoices(ids,field='assigned'){return `<div class="check-list">${S.supervisors.filter(s=>s.active||ids.includes(s.id)).map(s=>`<label class="check-item"><span class="avatar">${initials(s.name)}</span><span>${esc(s.name)}${s.active?'':' (inactive)'}</span><input type="checkbox" name="${field}" value="${s.id}" ${ids.includes(s.id)?'checked':''}></label>`).join('')}</div>`;}
function projectForm(id){if(!requireOwner())return;const p=id?project(id):{id:'',name:'',client:'',location:'',category:'Synthetic turf replacement',start:localISO(),end:shiftDate(30),status:'Active',assigned:[],description:'',aiInstructions:'Keep each caption factual and concise. Do not infer measurements, percentages, compliance or completion. Flag anything uncertain for owner review.',cadence:'weekdays',interval:2,weekday:5,time:'17:00',minimum:4};if(!p)return;openModal(id?'Edit project':'Start a new project','Define the work, tag the team and set the rhythm for site updates.',`<form id="project-form" data-id="${p.id}"><div id="form-error" class="form-error" role="alert"></div><div class="form-section">${icon('folder')} Project details</div><div class="form-grid">${formField('Project name *','name',p.name,'text','required maxlength="110" placeholder="e.g. School field replacement"',true)}${formField('Client / organisation *','client',p.client,'text','required maxlength="110"')}${formField('Site / location','location',p.location,'text','maxlength="140"')}<div class="field"><label for="f-category">Work category</label><select name="category" id="f-category">${['Synthetic turf replacement','Court resurfacing','Landscape works','General construction'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="f-status">Status</label><select name="status" id="f-status">${['Active','On hold','Completed'].map(c=>`<option ${p.status===c?'selected':''}>${c}</option>`).join('')}</select></div>${formField('Project start *','start',p.start,'date','required')}${formField('Target completion *','end',p.end,'date','required')}</div><div class="form-section">${icon('spark')} Context for picture captions</div><div class="form-grid"><div class="field full"><label for="f-description">Project description / scope *</label><textarea id="f-description" name="description" required maxlength="1400" rows="4" placeholder="Describe the work scope, materials, stages and what supervisors should document.">${esc(p.description)}</textarea><small>The description provides context for draft captions. Do not add unverified quantities or completion claims.</small></div><div class="field full"><label for="f-aiInstructions">Caption writing instructions</label><textarea id="f-aiInstructions" name="aiInstructions" maxlength="650" rows="3">${esc(p.aiInstructions)}</textarea></div></div><div class="form-section">${icon('users')} Tag supervisors</div>${S.supervisors.some(s=>s.active)?supervisorChoices(p.assigned):'<p class="small muted">Add a supervisor from the Supervisors page first. Projects may be saved unassigned.</p>'}<div class="form-section">${icon('bell')} Periodic photo prompts</div><div class="form-grid"><div class="field"><label for="f-cadence">How often?</label><select id="f-cadence" name="cadence">${[['daily','Every day'],['weekdays','Weekdays (Mon–Fri)'],['weekly','Weekly on a set day'],['interval','Every N days']].map(([v,l])=>`<option value="${v}" ${p.cadence===v?'selected':''}>${l}</option>`).join('')}</select></div>${formField('Prompt time · device local timezone','time',p.time,'time','required')}<div class="field ${p.cadence==='weekly'?'':'hidden'}" id="weekday-field"><label for="f-weekday">Day of week</label><select name="weekday" id="f-weekday">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}" ${Number(p.weekday)===i?'selected':''}>${d}</option>`).join('')}</select></div><div class="field ${p.cadence==='interval'?'':'hidden'}" id="interval-field"><label for="f-interval">Repeat every (days)</label><input name="interval" id="f-interval" type="number" min="1" max="90" value="${p.interval}"></div>${formField('Minimum photos per update','minimum',p.minimum,'number','required min="1" max="20"')}</div><div class="notice amber mt" style="margin-bottom:0">${icon('info')}<span>Demo reminders appear in the supervisor’s in-app inbox. Real scheduling and notification delivery require a backend.</span></div></form>`,`<button type="submit" class="btn primary" form="project-form">${icon('check')}${id?'Save changes':'Create project'}</button>`);}
async function saveProject(form){if(!requireOwner())return;const f=new FormData(form),id=form.dataset.id,existing=project(id);if(f.get('end')<f.get('start')){$('#form-error').textContent='Target completion must be on or after the project start date.';return;}const name=f.get('name').trim(),client=f.get('client').trim(),description=f.get('description').trim();if(!name||!client||!description){$('#form-error').textContent='Project name, client and scope must contain text.';return;}const payload={name,client,description,location:f.get('location').trim(),category:f.get('category'),start:f.get('start'),end:f.get('end'),status:f.get('status'),assigned:f.getAll('assigned').filter(id=>sup(id)),aiInstructions:f.get('aiInstructions').trim(),cadence:f.get('cadence'),interval:Math.min(90,Math.max(1,Number(f.get('interval'))||1)),weekday:Number(f.get('weekday')),time:f.get('time'),minimum:Number(f.get('minimum'))};let p;if(existing){Object.assign(existing,payload);p=existing;}else{const seq=Math.max(0,...S.projects.map(p=>Number(p.code.split('-').pop())||0))+1;p={...payload,id:uid('p'),code:`HH-026-${String(seq).padStart(3,'0')}`,hero:null,created:localISO()};S.projects.push(p);}addActivity(existing?'updated the project brief, team and reporting schedule.':'created the project and set its reporting schedule.',p.id);await save();closeModal();V.project=p.id;V.page='projects';V.tab='overview';render();toast(existing?'Project settings updated.':'Project created. Switch to a tagged supervisor to upload photos.');}
function supervisorForm(id){if(!requireOwner())return;const s=id?sup(id):{id:'',name:'',email:'',phone:'+65 ',active:true};if(!s)return;const assigned=S.projects.filter(p=>p.assigned.includes(id)).map(p=>p.id);openModal(id?'Edit supervisor':'Add a supervisor','Set contact details and choose which projects this person can see.',`<form id="supervisor-form" data-id="${s.id}"><div id="form-error" class="form-error" role="alert"></div><div class="form-grid">${formField('Full name *','name',s.name,'text','required maxlength="70"',true)}${formField('Email address *','email',s.email,'email','required maxlength="120"')}${formField('Mobile number','phone',s.phone,'tel','maxlength="30"')}<div class="field full"><label class="check-item"><span>Active supervisor</span><input name="active" type="checkbox" ${s.active?'checked':''}></label></div></div><div class="form-section">${icon('folder')} Assigned projects</div><div class="check-list">${S.projects.map(p=>`<label class="check-item"><span class="grow">${esc(p.name)}<br><small class="muted">${esc(p.code)}</small></span><input type="checkbox" name="projects" value="${p.id}" ${assigned.includes(p.id)?'checked':''}></label>`).join('')||'<p class="small muted">Projects can be assigned later.</p>'}</div><div class="notice mt" style="margin-bottom:0">${icon('info')}<span>Saving creates a local demo profile only. No invitation email or account credentials are generated.</span></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" type="submit" form="supervisor-form">${icon('check')}${id?'Save changes':'Add supervisor'}</button>`);}
async function saveSupervisor(form){if(!requireOwner())return;const f=new FormData(form),id=form.dataset.id,name=f.get('name').trim(),email=f.get('email').trim().toLowerCase();if(!name){$('#form-error').textContent='Enter a supervisor name.';return;}if(S.supervisors.some(s=>s.email.toLowerCase()===email&&s.id!==id)){$('#form-error').textContent='That email is already used by another supervisor.';return;}const data={name,email,phone:f.get('phone').trim(),active:f.has('active')};let s=sup(id);if(s)Object.assign(s,data);else{s={id:uid('s'),...data};S.supervisors.push(s);}const projectIds=f.getAll('projects');S.projects.forEach(p=>{p.assigned=p.assigned.filter(x=>x!==s.id);if(projectIds.includes(p.id))p.assigned.push(s.id);});addActivity(`${id?'updated':'added'} supervisor ${name}.`,projectIds[0]||null);await save();closeModal();render();toast(`${name} ${id?'updated':'added'} to the demo team.`);}
function taskForm(pid,id){if(!requireOwner())return;const t=id?S.tasks.find(t=>t.id===id):{id:'',project:pid||S.projects[0]?.id,type:'task',text:'',due:localISO(),repeat:'none',assigned:'all',priority:'Normal',done:false};const p=project(t?.project);if(!p){toast('Create a project before adding instructions.','error');return;}openModal(id?'Edit site instruction':'Add task or remark',esc(p.name),`<form id="task-form" data-id="${t.id}" data-project="${p.id}"><div id="form-error" class="form-error" role="alert"></div><div class="form-grid"><div class="field"><label for="f-type">Instruction type</label><select name="type" id="f-type"><option value="task" ${t.type==='task'?'selected':''}>Task to complete</option><option value="remark" ${t.type==='remark'?'selected':''}>Owner’s remark</option></select></div><div class="field"><label for="f-priority">Priority</label><select name="priority" id="f-priority"><option ${t.priority==='Normal'?'selected':''}>Normal</option><option ${t.priority==='High'?'selected':''}>High</option></select></div><div class="field full"><label for="f-text">Task or remark *</label><textarea name="text" id="f-text" required maxlength="700" rows="4" placeholder="e.g. Photograph each turf seam before the next work stage.">${esc(t.text)}</textarea></div>${formField('Due / display date *','due',t.due,'date','required')}<div class="field"><label for="f-repeat">Repeat</label><select name="repeat" id="f-repeat">${[['none','One-off'],['daily','Daily'],['weekly','Weekly']].map(([v,l])=>`<option value="${v}" ${t.repeat===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field full"><label for="f-assigned">Assign to</label><select name="assigned" id="f-assigned"><option value="all">All assigned supervisors</option>${p.assigned.map(id=>`<option value="${id}" ${t.assigned===id?'selected':''}>${esc(sup(id)?.name||'Former supervisor')}</option>`).join('')}</select><small>Recurring tasks advance to the next due date when completed. Recurring remarks are included in the scheduled prompt simulation on their due dates.</small></div></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" type="submit" form="task-form">${icon('plus')}${id?'Save instruction':'Add instruction'}</button>`);}
async function saveTask(form){if(!requireOwner())return;const f=new FormData(form),text=f.get('text').trim();if(!text){$('#form-error').textContent='Enter a task or remark.';return;}const old=S.tasks.find(t=>t.id===form.dataset.id);const t={project:form.dataset.project,type:f.get('type'),text,due:f.get('due'),repeat:f.get('repeat'),assigned:f.get('assigned'),priority:f.get('priority')};if(old)Object.assign(old,t);else S.tasks.push({id:uid('t'),done:false,...t});addActivity(`${old?'updated':'added'} a ${t.type}${t.repeat==='none'?'':` (${t.repeat})`}.`,t.project);await save();closeModal();render();toast('Site instruction saved.');}
async function toggleTask(id){const t=S.tasks.find(t=>t.id===id);if(!t||!visibleTasks(t.project).some(v=>v.id===id)||t.type!=='task')return;if(t.repeat!=='none'&&!t.done){const step=t.repeat==='daily'?1:7;let next=shiftDate(step,t.due);while(next<=localISO())next=shiftDate(step,next);addActivity(`completed recurring task: ${t.text} Next due ${dateLabel(next)}.`,t.project);t.due=next;toast('Task completed. The next recurring occurrence is now scheduled.');}else{t.done=!t.done;addActivity(`${t.done?'completed':'reopened'} task: ${t.text}`,t.project);toast(t.done?'Task marked complete.':'Task reopened.');}await save();render();}
function remarksForDate(pid,day){return S.tasks.filter(t=>t.project===pid&&t.type==='remark'&&t.due<=day&&(t.repeat==='none'||t.repeat==='daily'||Math.round((new Date(day+'T12:00:00')-new Date(t.due+'T12:00:00'))/86400000)%7===0));}
async function sendPrompt(pid,scheduled=false){if(!requireOwner())return;const p=project(pid);if(!p)return;const recipients=p.assigned.filter(id=>sup(id)?.active);if(!recipients.length){toast('Assign at least one active supervisor first.','error');return;}const when=scheduled?nextPrompt(p):new Date();if(!when){toast('No upcoming prompt falls within this project timeline.','error');return;}const day=localISO(when);let count=0;for(const id of recipients){const notes=remarksForDate(pid,day).filter(t=>t.assigned==='all'||t.assigned===id).map(t=>t.text);S.notifications.push({id:uid('n'),project:pid,to:id,kind:'prompt',text:`${scheduled?'Simulated scheduled prompt':'Photo update requested'}: please submit at least ${p.minimum} progress photos for ${p.name}.${notes.length?' Owner remarks: '+notes.join(' '):''}`,created:stamp(),scheduledFor:when.toISOString(),read:false,fulfilled:false,minimum:p.minimum});count++;}addActivity(`created ${count} in-app photo prompt${count!==1?'s':''}${scheduled?' for '+dateLabel(day):''}.`,pid);await save();render();toast(`Demo prompt added to ${count} supervisor inbox${count!==1?'es':''}. No external message sent.`);}
function uploadForm(pid){if(isOwner()){toast('Switch to the supervisor view to submit a site update.','error');return;}const ps=visibleProjects();if(!ps.length){toast('This supervisor has no assigned projects.','error');return;}const p=ps.find(p=>p.id===pid)||ps[0];pendingUploads=[];openModal('Submit a site update','Upload your photos. Add the work stage. Let the owner handle the report.',`<form id="upload-form"><div id="form-error" class="form-error" role="alert"></div><div class="form-grid"><div class="field full"><label for="upload-project">Assigned project *</label><select name="project" id="upload-project">${ps.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label for="upload-stage">Work stage *</label><select name="stage" id="upload-stage">${STAGES.map(s=>`<option ${s==='Joining & gamelines'?'selected':''}>${s}</option>`).join('')}</select></div>${formField('Photo record date *','date',localISO(),'date','required max="'+localISO()+'"')}</div><div class="upload-drop mt" id="upload-drop">${icon('camera')}<h3>Add your site photos</h3><p>Drop photos here, choose from your device, or use the camera.<br>JPEG, PNG or WebP · up to 20 photos · 15 MB each</p><div class="flex wrap" style="justify-content:center">${button('Choose photos','choose-files','upload','primary')}${button('Take a photo','take-photo','camera','')}</div><input id="upload-files" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden><input id="camera-file" type="file" accept="image/*" capture="environment" hidden><div style="margin-top:15px"><button class="text-btn" data-act="sample-photos" type="button" style="font-size:11px">${icon('photo')} Use 4 SACPS sample photos</button></div></div><div class="upload-thumbs" id="upload-thumbs"></div><div class="field mt"><label for="upload-note">Site note / context for this update</label><textarea id="upload-note" name="note" maxlength="500" rows="3" placeholder="What work is shown? Which part of the site? Anything the owner should know?"></textarea><small>You can also add a specific note under each photo above.</small></div><label class="check-item mt"><span class="grow">Generate draft captions after upload<br><small class="muted">Simulated AI · owner approval required</small></span><input type="checkbox" name="generate" checked></label><div class="notice mt" style="margin-bottom:0">${icon('shield')}<span>Photos stay on this device in this demo. Real shared storage, secure access and AI image analysis are not connected.</span></div></form>`,button('Cancel','modal-close')+`<button type="submit" class="btn primary" form="upload-form" id="upload-submit">${icon('upload')}Submit update</button>`);const drop=$('#upload-drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragging')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragging');addFiles(e.dataTransfer.files)});}
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('The image could not be decoded.'));im.src=src;});}
async function resizeFile(file){if(file.size>15*1024*1024)throw new Error(`${file.name}: over the 15 MB limit.`);if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error(`${file.name}: use JPEG, PNG or WebP. Convert HEIC photos first.`);const url=URL.createObjectURL(file);try{const im=await loadImage(url);const scale=Math.min(1,1600/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));const ctx=c.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);return {id:uid('temp'),src:c.toDataURL('image/jpeg',.88),fileName:file.name,note:'',source:null};}finally{URL.revokeObjectURL(url);}}
async function addFiles(files){if(uploadBusy)return;const room=20-pendingUploads.length;if(room<=0){toast('A single update can contain up to 20 photos.','error');return;}if(files.length>room)toast(`Only the first ${room} additional photos will be added.`);uploadBusy=true;const submit=$('#upload-submit');if(submit)submit.disabled=true;try{for(const file of [...files].slice(0,room)){try{pendingUploads.push(await resizeFile(file));}catch(e){toast(e.message,'error');}}renderUploadThumbs();}finally{uploadBusy=false;if(submit)submit.disabled=false;}}
function renderUploadThumbs(){const el=$('#upload-thumbs');if(!el)return;el.innerHTML=pendingUploads.map((p,i)=>`<div class="upload-thumb"><img src="${p.src}" alt="Photo ${i+1} preview"><button type="button" class="icon-btn" data-act="upload-remove" data-id="${p.id}" aria-label="Remove photo ${i+1}">${icon('close')}</button><p>${esc(p.fileName)}</p><textarea class="upload-note" maxlength="220" data-upload-note="${p.id}" aria-label="Note for photo ${i+1}" placeholder="Specific note (optional)">${esc(p.note)}</textarea></div>`).join('');}
function addSamplePhotos(){if($('#upload-project')?.value!=='p1'){toast('The supplied SACPS photos can only be added to the SACPS demonstration project. Use your own photos for this project.','error');return;}if(pendingUploads.length>16){toast('There is room for fewer than 4 sample photos.','error');return;}[20,23,28,31].forEach(n=>pendingUploads.push({id:uid('temp'),src:ASSET.photos[n],source:n,fileName:`SACPS-sample-${n}.jpg`,note:SOURCE_TITLES[n-1]}));renderUploadThumbs();toast('Four supplied-report photos added. Original timestamps remain visible.');}
function draftCaption(ph){const p=project(ph.project);if(ph.source)return SAMPLE_CAPTIONS[ph.source-1];const note=String(ph.note||'').trim().replace(/\s+/g,' ');const context=String(p?.description||'').trim().split(/[.!?](?:\s|$)/)[0];let text=`${ph.stage}: site-progress photograph for ${p?.name||'the project'}.`;if(note)text+=` Site note: ${note.replace(/[.!?]$/,'')}.`;else text+=' No specific activity was supplied; owner clarification is required.';if(context&&text.length<245)text+=` Scope context: ${context.slice(0,140)}.`;if(text.length>420)text=text.slice(0,417)+'…';return text;}
async function submitUpload(form){if(uploadBusy||isOwner())return;const f=new FormData(form),pid=f.get('project'),p=project(pid);if(!canAccess(p)){$('#form-error').textContent='You are not assigned to that project.';return;}if(!pendingUploads.length){$('#form-error').textContent='Add at least one photograph before submitting.';return;}if(f.get('date')>localISO()){$('#form-error').textContent='The photo record date cannot be in the future.';return;}if(pendingUploads.some(ph=>ph.source)&&pid!=='p1'){$('#form-error').textContent='The SACPS sample photos cannot be submitted under another project.';return;}uploadBusy=true;const btn=$('#upload-submit');btn.disabled=true;btn.innerHTML=icon('refresh')+' Saving update…';const count=pendingUploads.length;try{const newPhotos=pendingUploads.map(ph=>{const note=[ph.note,f.get('note').trim()].filter(Boolean).join(' — ').slice(0,720);const item={id:uid('ph'),project:pid,supervisor:V.supervisor,src:ph.src,source:ph.source,fileName:ph.fileName,stage:ph.source?SOURCE_STAGE(ph.source):f.get('stage'),title:ph.source?SOURCE_TITLES[ph.source-1]:f.get('stage'),note,date:f.get('date'),uploadedAt:stamp(),status:f.has('generate')?'review':'queued',caption:'',approvedBy:null,approvedAt:null,revision:1};if(f.has('generate'))item.caption=draftCaption(item);return item;});await new Promise(r=>setTimeout(r,650));S.photos.push(...newPhotos);S.notifications.forEach(n=>{if(n.to===V.supervisor&&n.project===pid&&n.kind==='prompt'&&!n.fulfilled){n.submittedCount=(n.submittedCount||0)+count;n.fulfilled=n.submittedCount>=(n.minimum||p.minimum);n.read=true;}});addActivity(`submitted ${count} photo${count!==1?'s':''}${f.has('generate')?' with simulated draft captions':''}.`,pid);await save();uploadBusy=false;closeModal();V.page='uploads';V.project=null;V.query='';V.filter='all';render();toast(`${count} photo${count!==1?'s':''} submitted. ${f.has('generate')?'Draft captions are awaiting owner review.':'The owner can generate captions in the review queue.'}`);}catch(e){uploadBusy=false;btn.disabled=false;btn.innerHTML=icon('upload')+'Submit update';toast('The update could not be saved. Please try again.','error');console.error(e);}}
function photoModal(id){const ph=S.photos.find(p=>p.id===id);if(!ph||!canAccess(project(ph.project))||(!isOwner()&&ph.supervisor!==V.supervisor))return;openModal(esc(ph.title),`${esc(project(ph.project)?.code)} · ${dateLabel(ph.date)} · ${esc(sup(ph.supervisor)?.name||'Former supervisor')}`,`<img class="lightbox-image" src="${ph.src}" alt="${esc(ph.title)}"><div class="flex wrap mb">${statusBadge(ph.status)}${badge(ph.stage,'gray')}${ph.source?badge(`Supplied report · photo ${ph.source}`,'gray'):''}</div><p class="lightbox-caption">${esc(ph.caption||'Caption not generated yet.')}</p><p class="small muted mt" style="white-space:pre-wrap;overflow-wrap:anywhere">Site note: ${esc(ph.note||'None')}</p>${ph.source?'<p class="small muted mt" style="font-size:10px">Submission dates and statuses are simulated. Any timestamp visible inside the original photograph is unchanged.</p>':''}`,button('Close','modal-close'),'wide');}
async function generateCaptions(ids){if(!requireOwner()||aiBusy)return;const list=S.photos.filter(p=>ids.includes(p.id));if(!list.length){toast('No photos need captions in this view.');return;}aiBusy=true;toast(`Generating ${list.length} simulated draft caption${list.length!==1?'s':''}…`);await new Promise(r=>setTimeout(r,750));for(const ph of list){ph.caption=draftCaption(ph);ph.status='review';ph.approvedAt=null;ph.approvedBy=null;ph.revision++;delete ph.rejection;}addActivity(`generated ${list.length} simulated caption draft${list.length!==1?'s':''}.`,list[0].project);await save();aiBusy=false;render();toast('Drafts ready. Review the wording before approving.');}
async function approvePhotos(ids){if(!requireOwner())return;const eligible=S.photos.filter(p=>ids.includes(p.id)&&p.caption.trim()&&p.status==='review');if(!eligible.length){toast('Only review-ready captions can be approved.','error');return;}eligible.forEach(p=>{p.status='approved';p.approvedBy='Owner (demo)';p.approvedAt=stamp();V.selected.delete(p.id)});addActivity(`approved ${eligible.length} caption${eligible.length!==1?'s':''} for PDF export.`,eligible[0].project);await save();render();toast(`${eligible.length} photo caption${eligible.length!==1?'s':''} approved for reports.`);}
function approveConfirmation(ids){const list=S.photos.filter(p=>ids.includes(p.id)&&p.caption.trim()&&p.status==='review');if(!list.length){toast('Select review-ready captions first.','error');return;}confirmDialog('Confirm your caption review',`You are approving ${list.length} photo caption${list.length!==1?'s':''} for inclusion in the progress report. Please confirm that you have checked every selected photograph and its description. This does not certify the construction work or payment entitlement.`,()=>approvePhotos(list.map(p=>p.id)),'I have reviewed these captions');}
function requestChanges(id){if(!requireOwner())return;const ph=S.photos.find(p=>p.id===id);if(!ph)return;openModal('Ask for clarification',esc(ph.title),`<form id="changes-form" data-id="${id}"><div class="field"><label for="change-note">What should the supervisor clarify? *</label><textarea id="change-note" name="reason" required maxlength="500" placeholder="e.g. Please identify which turf seam this photo shows."></textarea></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" form="changes-form" type="submit">${icon('send')}Request changes</button>`,'narrow');}
function clarificationForm(id){const ph=S.photos.find(p=>p.id===id);if(!ph||isOwner()||ph.supervisor!==V.supervisor||!canAccess(project(ph.project)))return;openModal('Clarify this photo',esc(ph.title),`<div class="notice amber">${icon('note')}<span>${esc(ph.rejection||'Please add the missing context.')}</span></div><form id="clarify-form" data-id="${id}"><div class="field"><label for="clarify-note">Updated site note *</label><textarea id="clarify-note" name="note" required maxlength="700">${esc(ph.note)}</textarea></div></form>`,button('Cancel','modal-close')+`<button class="btn primary" form="clarify-form" type="submit">${icon('send')}Resubmit for review</button>`,'narrow');}
function reportsPage(){if(!S.projects.length)return empty('Create a project first','Reports are assembled from owner-approved project photographs.','project-new','New project');if(!project(V.reportProject))V.reportProject=S.projects[0].id;const p=project(V.reportProject);return `<div class="page-heading"><div><h1>Progress reports</h1><p>A reviewed photo record, ready to accompany a client payment submission.</p></div>${badge('Approved photos only','green','shield')}</div><div class="tabs"><button class="tab ${V.tab!=='history'?'active':''}" data-act="report-tab" data-tab="builder">Report builder</button><button class="tab ${V.tab==='history'?'active':''}" data-act="report-tab" data-tab="history">Export history ${badge(String(S.reports.length),'gray')}</button></div>${V.tab==='history'?(S.reports.length?`<div class="panel">${S.reports.slice().reverse().map(r=>`<div class="report-history"><span class="project-symbol">${icon('file')}</span><div class="grow"><h3>${esc(r.projectName)}</h3><p>${esc(r.code)} · ${dateLabel(r.from)} – ${dateLabel(r.to)} · ${r.photos.length} photos · ${dateLabel(r.exported,{day:'numeric',month:'short',year:'numeric'})}</p></div>${badge('Exported','green')}${button('Download again','report-redownload','download','sm',`data-id="${r.id}"`)}<button class="icon-btn" data-act="report-delete" data-id="${r.id}" aria-label="Delete export history entry">${icon('trash')}</button></div>`).join('')}</div>`:empty('No exported reports yet','Create a report from approved photos. Each export saves a local snapshot of the reviewed captions.')):`<div class="report-layout"><section class="panel report-control"><h3 style="margin-bottom:19px">Report details</h3><div class="field"><label for="report-project">Project</label><select id="report-project">${S.projects.map(p=>`<option value="${p.id}" ${V.reportProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="inline-pair"><div class="field"><label for="report-from">From</label><input type="date" id="report-from" value="${p.start}"></div><div class="field"><label for="report-to">To</label><input type="date" id="report-to" value="${p.end<localISO()?p.end:localISO()}"></div></div><div class="field"><label for="report-client">Prepared for</label><input id="report-client" maxlength="110" value="${esc(p.client)}"></div><div class="field"><label for="report-ref">Claim / reference (optional)</label><input id="report-ref" maxlength="70" placeholder="e.g. Progress claim 01"></div><div class="field"><label for="report-summary">Owner’s report summary</label><textarea id="report-summary" maxlength="600" rows="4" placeholder="Optional summary for the cover page.">Photographic record of the documented work stages. This demonstration report contains sample review decisions and is not a payment claim or certification of completed works.</textarea></div><div class="notice" id="report-readiness">${icon('shield')}<span>Calculating approved photographs…</span></div>${button('Export PDF report','report-export','download','primary','style="width:100%" id="export-pdf"')}<p class="small muted" style="font-size:9px;text-align:center;margin-top:10px">A4 PDF · Numbered photos · 4 photos per page</p><div class="divider"></div><p class="small muted" style="font-size:10px;line-height:1.8">Every export is labelled <strong>DEMONSTRATION</strong>. Internal tasks, contact details and unapproved captions are excluded. Downloading does not send anything to a client.</p></section><section class="report-preview"><div class="flex between" style="width:100%;margin-bottom:4px"><span class="eyebrow" style="font-size:9px">DOCUMENT PREVIEW</span>${badge('Sample output','gray')}</div><div id="report-canvas" style="width:100%;display:flex;justify-content:center"><p class="muted small">Building preview…</p></div><div class="report-nav">${button('Previous','report-prev','left','sm','id="report-prev"')}<span id="report-page-count">Page 1</span>${button('Next','report-next','chev','sm','id="report-next"')}</div></section></div>`}`;}
function getReportSnapshot(){const p=project($('#report-project')?.value||V.reportProject);if(!p)return null;const from=$('#report-from')?.value||p.start,to=$('#report-to')?.value||localISO();const range=projectPhotos(p.id).filter(ph=>ph.date>=from&&ph.date<=to);return {id:uid('r'),project:p.id,projectName:p.name,code:p.code,category:p.category,client:$('#report-client')?.value?.trim()||p.client,reference:$('#report-ref')?.value?.trim()||'',summary:$('#report-summary')?.value?.trim()||'',from,to,exported:stamp(),photos:structuredClone(range.filter(ph=>ph.status==='approved'&&ph.caption.trim()).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id,undefined,{numeric:true}))).map(ph=>({...ph,supervisorName:sup(ph.supervisor)?.name||'Former supervisor'})),excluded:range.filter(ph=>ph.status!=='approved').length};}
let previewToken=0;
async function refreshReportPreview(){if(V.page!=='reports'||V.tab==='history'||!$('#report-canvas'))return;const token=++previewToken,r=getReportSnapshot();if(!r)return;reportPreview=r;const invalid=!r.from||!r.to||r.from>r.to;const ready=$('#report-readiness'),exportBtn=$('#export-pdf');if(ready)ready.innerHTML=icon('shield')+`<span>${invalid?'Choose a valid report date range.':`<strong>${r.photos.length} approved photo${r.photos.length!==1?'s':''}</strong> will be included.<br>${r.excluded} unapproved photo${r.excluded!==1?'s':''} excluded from this date range.`}</span>`;if(exportBtn)exportBtn.disabled=invalid||r.photos.length===0;const total=1+Math.ceil(r.photos.length/4);V.reportPage=Math.max(0,Math.min(V.reportPage,total-1));try{const canvas=await drawReportPage(r,V.reportPage);if(token!==previewToken||!$('#report-canvas'))return;$('#report-canvas').replaceChildren(canvas);$('#report-page-count').textContent=`Page ${V.reportPage+1} of ${total}`;$('#report-prev').disabled=V.reportPage===0;$('#report-next').disabled=V.reportPage===total-1;}catch(e){if($('#report-canvas'))$('#report-canvas').innerHTML='<p class="small muted">An image could not be loaded for the preview. Please reload and try again.</p>';toast('Preview could not load a photograph.','error');console.error(e);}}
const imageCache=new Map();async function reportImage(src){if(!imageCache.has(src))imageCache.set(src,loadImage(src));return imageCache.get(src);}
function canvasText(ctx,text,x,y,maxWidth,{font=10,color='#253c2c',weight=400,line=1.45,maxLines=99}={}){ctx.fillStyle=color;ctx.font=`${weight} ${font}px Arial,sans-serif`;ctx.textBaseline='top';const lines=[];for(const para of String(text||'').split('\n')){let row='';for(const word of para.split(/\s+/)){if(!word)continue;const candidate=row?row+' '+word:word;if(ctx.measureText(candidate).width<=maxWidth){row=candidate;continue;}if(row){lines.push(row);row='';}if(ctx.measureText(word).width<=maxWidth)row=word;else{let part='';for(const char of word){if(ctx.measureText(part+char).width>maxWidth){lines.push(part);part=char;}else part+=char;}row=part;}}lines.push(row);}if(lines.length>maxLines){const last=lines.slice(0,maxLines);last[maxLines-1]=last[maxLines-1].replace(/\s+\S*$/,'')+'…';last.forEach((s,i)=>ctx.fillText(s,x,y+i*font*line));return {height:last.length*font*line,lines:lines.length};}lines.forEach((s,i)=>ctx.fillText(s,x,y+i*font*line));return {height:lines.length*font*line,lines:lines.length};}
function measureLines(ctx,text,w,font){ctx.font=`400 ${font}px Arial,sans-serif`;let count=0;for(const para of String(text||'').split('\n')){let row='';for(const word of para.split(/\s+/)){if(!word)continue;if(ctx.measureText(row?row+' '+word:word).width>w){if(row)count++;row=word;while(ctx.measureText(row).width>w){let cut=row.length-1;while(cut>0&&ctx.measureText(row.slice(0,cut)).width>w)cut--;count++;row=row.slice(Math.max(1,cut));}}else row=row?row+' '+word:word;}count++;}return count;}
function containImage(ctx,im,x,y,w,h){const scale=Math.min(w/im.naturalWidth,h/im.naturalHeight);ctx.drawImage(im,x+(w-im.naturalWidth*scale)/2,y+(h-im.naturalHeight*scale)/2,im.naturalWidth*scale,im.naturalHeight*scale);}
async function drawReportPage(r,pageIndex){const c=document.createElement('canvas');c.width=1190;c.height=1684;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#ffffff';ctx.fillRect(0,0,595,842);const logo=await reportImage(ASSET.logo);ctx.drawImage(logo,34,22,143,63);const total=1+Math.ceil(r.photos.length/4);canvasText(ctx,'H&H RESOURCES / FIELD REPORTS',326,37,235,{font:7.7,color:'#738168',weight:600});canvasText(ctx,'DEMONSTRATION · NOT FOR PAYMENT SUBMISSION',326,52,225,{font:6.3,color:'#a77b3d',weight:600});ctx.strokeStyle='#dce4d4';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(36,806);ctx.lineTo(559,806);ctx.stroke();canvasText(ctx,`${r.code}  ·  Approved-caption demonstration`,36,817,400,{font:7.3,color:'#89927f'});canvasText(ctx,`${pageIndex+1} / ${total}`,527,817,35,{font:7.3,color:'#89927f'});
 if(pageIndex===0){canvasText(ctx,'PHOTOGRAPHIC PROGRESS RECORD',39,120,520,{font:8,color:'#73876a',weight:600});canvasText(ctx,'Progress report',36,145,523,{font:31,weight:600,color:'#193c2b',line:1.2});canvasText(ctx,r.projectName,38,192,519,{font:19,weight:500,color:'#315139',line:1.3,maxLines:3});const y=284;ctx.fillStyle='#f0f3e9';ctx.fillRect(38,y,519,229);if(r.photos.length){const coverPhoto=r.photos.find(ph=>ph.source===32)||r.photos[r.photos.length-1];const im=await reportImage(coverPhoto.src);containImage(ctx,im,38,y,519,229);}else canvasText(ctx,'Approve photo captions to populate this report.',72,y+103,451,{font:12,color:'#7b8b6c'});canvasText(ctx,'A PHOTO RECORD — NOT A COMPLETION CERTIFICATE',38,523,519,{font:7,color:'#8d997f'});const meta=(label,value,x,y,w)=>{canvasText(ctx,label,x,y,w,{font:7.3,color:'#8a977e',weight:600});canvasText(ctx,value,x,y+15,w,{font:10,color:'#2b422d',line:1.3,maxLines:3});};meta('REPORTING PERIOD',`${dateLabel(r.from,{day:'numeric',month:'short',year:'numeric'})} — ${dateLabel(r.to,{day:'numeric',month:'short',year:'numeric'})}`,38,552,265);meta('APPROVED PHOTOGRAPHS',String(r.photos.length),345,552,210);meta('PREPARED FOR',r.client,38,600,267);meta('REFERENCE',r.reference||r.code,345,600,210);canvasText(ctx,'OWNER’S REPORT SUMMARY',38,666,519,{font:7.3,color:'#8a977e',weight:600});canvasText(ctx,r.summary||'Photographic record of the owner-reviewed work-stage descriptions.',38,683,518,{font:9,line:1.45,maxLines:8});canvasText(ctx,'Demo approvals and dates are illustrative. Verify originals before any real client submission.',38,787,519,{font:7,color:'#947a51'});
 }else{canvasText(ctx,r.projectName,187,72,370,{font:8.5,weight:600,color:'#47623d',maxLines:2,line:1.2});const list=r.photos.slice((pageIndex-1)*4,pageIndex*4);for(let i=0;i<list.length;i++){const ph=list[i],x=36+(i%2)*269,y=108+Math.floor(i/2)*344,w=254,h=332;ctx.strokeStyle='#dce3d5';ctx.lineWidth=.7;ctx.strokeRect(x,y,w,h);ctx.fillStyle='#f1f5eb';ctx.fillRect(x+.4,y+.4,w-.8,27);canvasText(ctx,`PHOTO ${String((pageIndex-1)*4+i+1).padStart(2,'0')}`,x+10,y+9,100,{font:8,weight:600,color:'#4e703e'});canvasText(ctx,dateLabel(ph.date,{day:'numeric',month:'short',year:'numeric'}),x+154,y+9,90,{font:7.3,color:'#748268'});const im=await reportImage(ph.src);ctx.fillStyle='#fafbf7';ctx.fillRect(x+7,y+33,w-14,163);containImage(ctx,im,x+7,y+33,w-14,163);const titleHeight=canvasText(ctx,ph.title,x+10,y+207,w-20,{font:10,weight:600,color:'#294a32',line:1.2,maxLines:2}).height;const captionTop=y+211+titleHeight;const room=(y+306)-captionTop;let font=9.1;while(font>6.3&&measureLines(ctx,ph.caption,w-20,font)*font*1.33>room)font-=.25;canvasText(ctx,ph.caption,x+10,captionTop,w-20,{font,color:'#65745e',line:1.33});canvasText(ctx,`${ph.source?'Source photo '+ph.source+' · ':''}Owner-reviewed · Demo`,x+10,y+317,w-20,{font:6.9,color:'#94a087'});}}
 return c;}
/* Minimal PDF 1.4 writer. It embeds A4 canvas pages as JPEG images.
 * No remote renderer or library is required. Raster pages preserve Unicode and
 * the exact preview layout; text is not selectable in this demonstration PDF.
 */
function canvasesToPDF(canvases){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const write=s=>{const b=typeof s==='string'?encoder.encode(s):s;chunks.push(b);length+=b.length;};const object=(n,parts)=>{offsets[n]=length;write(`${n} 0 obj\n`);parts.forEach(write);write('\nendobj\n');};write('%PDF-1.4\n%HNH-REPORT\n');object(1,['<< /Type /Catalog /Pages 2 0 R >>']);const ids=canvases.map((_,i)=>3+i*3);object(2,[`<< /Type /Pages /Count ${canvases.length} /Kids [${ids.map(n=>`${n} 0 R`).join(' ')}] >>`]);canvases.forEach((c,i)=>{const page=ids[i],image=page+1,content=page+2;const binary=atob(c.toDataURL('image/jpeg',.93).split(',')[1]);const data=Uint8Array.from(binary,ch=>ch.charCodeAt(0));const commands='q\n595.28 0 0 841.89 0 0 cm\n/Im0 Do\nQ\n';object(page,[`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${image} 0 R >> >> /Contents ${content} 0 R >>`]);object(image,[`<< /Type /XObject /Subtype /Image /Width ${c.width} /Height ${c.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n`,data,'\nendstream']);object(content,[`<< /Length ${encoder.encode(commands).length} >>\nstream\n${commands}endstream`]);});const xref=length;write(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);for(let n=1;n<offsets.length;n++)write(`${String(offsets[n]).padStart(10,'0')} 00000 n \n`);write(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
function downloadBlob(blob,filename){const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
let exporting=false;
async function exportReport(snapshot=null){if(!requireOwner()||exporting)return;const r=snapshot||getReportSnapshot();if(!r||!r.photos.length){toast('Approve at least one photo before exporting.','error');return;}if(!r.from||!r.to||r.from>r.to){toast('Choose a valid reporting period.','error');return;}exporting=true;const btn=$('#export-pdf');if(btn){btn.disabled=true;btn.innerHTML=icon('refresh')+' Building PDF…';}toast(`Preparing ${1+Math.ceil(r.photos.length/4)} report pages…`);try{const pages=[];for(let n=0;n<1+Math.ceil(r.photos.length/4);n++){pages.push(await drawReportPage(r,n));await new Promise(resolve=>setTimeout(resolve,0));}const blob=canvasesToPDF(pages);downloadBlob(blob,`HNH_${r.code}_Progress_Report_${r.to}_DEMO.pdf`);if(!snapshot){S.reports.push(r);addActivity(`exported a demonstration report with ${r.photos.length} approved photos.`,r.project);await save();}toast('PDF downloaded. A reviewed snapshot is saved in export history.');}catch(e){toast('PDF export failed. Check that all photos load, then try again.','error');console.error(e);}finally{exporting=false;if(btn){btn.disabled=false;btn.innerHTML=icon('download')+'Export PDF report';}}}
function helpModal(){openModal('A site update, end to end','A working local demo of your owner → supervisor → review → PDF workflow.',`<div class="help-steps"><div class="help-step"><span class="step-number">1</span><div><strong>Create and organise · Owner</strong>Use New project to set the scope, start and target dates, tagged supervisors, prompt frequency and photo requirements. Add tasks or remarks at any time.</div></div><div class="help-step"><span class="step-number">2</span><div><strong>Capture the work · Supervisor</strong>Switch views at the top and choose a demo supervisor. Only their assigned projects appear. Upload your own photographs or add four sample SACPS photos.</div></div><div class="help-step"><span class="step-number">3</span><div><strong>Review the captions · Owner</strong>Open Caption review, edit descriptions, request clarification or approve reviewed captions together. Editing an approved caption removes its approval.</div></div><div class="help-step"><span class="step-number">4</span><div><strong>Prepare the report · Owner</strong>Choose a project and reporting period, inspect the A4 preview and export a PDF. Only approved captions enter the report. Previous exports keep their own snapshots.</div></div></div><div class="divider"></div><h3 style="margin-bottom:10px">What is real in this demo</h3><p class="description" style="font-size:12px">Project and supervisor CRUD, assignment filtering, tasks, recurrence settings, photo uploads, saved local data, editable captions, approval workflow, report preview and downloadable PDFs all work in this browser.</p><h3 style="margin:20px 0 10px">What is simulated</h3><p class="description" style="font-size:12px">The role switch is not authentication. No backend enforces access. AI captions are contextual templates, not image recognition. Prompt buttons create demo inbox entries; nothing sends email, WhatsApp or push, and no scheduler runs when the app is closed. Devices do not sync. Do not upload confidential client or staff data to a public copy of this demo.</p><div class="notice mt">${icon('photo')}<span><strong>Sample provenance.</strong> The 36 photos, work-stage titles and H&H logo come from your supplied “Progress Report for SACPS(1).pdf”. The cover identifies St Anthony’s Canossian Primary School. Supervisor names, schedules, submission dates, review decisions and the two other projects are fictional demo data. Original photo timestamps are unchanged.</span></div><div class="notice">${icon('info')}<span>PDFs use the same A4 page artwork as the preview (raster-based; text is not selectable). The sample export is watermarked as a demonstration, not a payment submission.</span></div><div class="flex wrap between"><div><strong style="font-size:12px">${esc(storageMode)}</strong><p class="small muted" style="font-size:10px">Reset removes edits, uploads, profiles and export history from this browser.</p></div>${button('Reset demo data','reset-demo','refresh','danger sm')}</div>`,button('Install / add to home screen','install','download','')+button('Start exploring','modal-close','arrow','primary'),'wide');}
async function installApp(){if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;toast(choice.outcome==='accepted'?'Installation requested.':'You can install the app later from the browser menu.');return;}openModal('Use Field Reports as an app','The ZIP package contains the installable PWA files.',`<div class="help-steps"><div class="help-step"><span class="step-number">1</span><div><strong>Serve the PWA package</strong>Extract the ZIP and serve the folder over HTTPS, or run <code>python3 -m http.server 8080</code> in that folder and open <code>http://localhost:8080</code>. The standalone HTML works by double-clicking, but is not installable by itself.</div></div><div class="help-step"><span class="step-number">2</span><div><strong>Android / desktop Chrome</strong>Open the hosted demo and use the browser’s Install app / Add to Home screen option. The in-app install prompt appears when the browser makes it available.</div></div><div class="help-step"><span class="step-number">3</span><div><strong>iPhone / iPad</strong>Open the hosted demo in Safari, then use Share → Add to Home Screen. The ZIP must be served over HTTPS for a normal remote installation.</div></div></div><div class="notice mt">${icon('shield')}<span>The app caches its interface and sample images for offline use after the first hosted visit. Uploads and changes stay in this browser, not on the server. The role switch remains a demo, not secure access control.</span></div>`,button('Close','modal-close'),'narrow');}
function updateReviewCard(ph){const card=$(`[data-card="${ph.id}"]`);if(!card)return;const stat=card.querySelector('[data-status]');if(stat)stat.innerHTML=statusBadge(ph.status);const selection=card.querySelector('[data-select]');if(selection){selection.disabled=ph.status!=='review';selection.checked=V.selected.has(ph.id);}card.classList.toggle('selected',V.selected.has(ph.id));const approve=card.querySelector('[data-act="approve-one"]');if(approve){approve.disabled=!ph.caption.trim()||ph.status==='approved';approve.className='btn sm primary';approve.innerHTML=icon('check')+'Approve';}const allApprove=$('[data-act="approve-all"]');if(allApprove)allApprove.disabled=!reviewRows().some(p=>p.status==='review');const el=$('#selected-count');if(el)el.textContent=`${V.selected.size} selected`;const selectedButton=$('[data-act="approve-selected"]');if(selectedButton)selectedButton.disabled=V.selected.size===0;}
async function handleClick(e){const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,id=b.dataset.id;
 try{switch(a){
 case 'nav':changePage(b.dataset.page);break;
 case 'role':if(uploadBusy)return;if(b.dataset.role==='supervisor'&&!S.supervisors.some(s=>s.active)){toast('Add or activate a supervisor first.','error');return;}V.role=b.dataset.role;if(!sup(V.supervisor)?.active)V.supervisor=S.supervisors.find(s=>s.active)?.id;changePage('overview');break;
 case 'project-new':projectForm();break;case 'project-edit':projectForm(id);break;
 case 'project-open':if(canAccess(project(id)))changePage('projects',id);else toast('You are not assigned to this project.','error');break;
 case 'tab':V.tab=b.dataset.tab;render();break;
 case 'project-review':if(!requireOwner())return;V.reviewProject=id;V.reviewFilter='pending';changePage('review');break;
 case 'project-report':if(!requireOwner())return;V.reportProject=id;V.reportPage=0;changePage('reports');break;
 case 'task-new':taskForm(id);break;case 'task-edit':taskForm(null,id);break;case 'task-toggle':await toggleTask(id);break;
 case 'task-delete':if(!requireOwner())return;confirmDialog('Delete this instruction?','This removes the task or remark from the project for all tagged supervisors.',async()=>{const t=S.tasks.find(t=>t.id===id);S.tasks=S.tasks.filter(t=>t.id!==id);addActivity('deleted a site instruction.',t?.project);await save();render();toast('Instruction removed.');},'Delete instruction',true);break;
 case 'supervisor-new':supervisorForm();break;case 'supervisor-edit':supervisorForm(id);break;
 case 'supervisor-toggle':if(!requireOwner())return;{const s=sup(id);if(!s)return;confirmDialog(s.active?'Deactivate supervisor?':'Activate supervisor?',s.active?`${s.name} will be removed from the demo supervisor selector. Their photographs, project assignments and history will be preserved.`:`${s.name} will be available in the demo supervisor selector again.`,async()=>{s.active=!s.active;await save();render();toast(`${s.name} ${s.active?'activated':'deactivated'}.`);},s.active?'Deactivate':'Activate');}break;
 case 'supervisor-delete':if(!requireOwner())return;{const s=sup(id);if(!s)return;if(S.photos.some(p=>p.supervisor===id)){openModal('Keep the project record intact','This supervisor has submitted project photographs.',`<p class="description" style="font-size:13px">Deleting this profile would orphan the photo record. Deactivate ${esc(s.name)} instead; this preserves their submissions and removes their demo access.</p>`,button('Close','modal-close')+button('Deactivate instead','deactivate-instead','pause','primary',`data-id="${id}"`),'narrow');return;}confirmDialog('Delete supervisor?',`Delete ${s.name} from the local demo? Their project assignments and pending prompts will be removed. Tasks assigned to them will become visible to all supervisors on their respective projects.`,async()=>{S.supervisors=S.supervisors.filter(x=>x.id!==id);S.projects.forEach(p=>p.assigned=p.assigned.filter(x=>x!==id));S.notifications=S.notifications.filter(n=>n.to!==id);S.tasks.forEach(t=>{if(t.assigned===id)t.assigned='all'});await save();render();toast('Supervisor deleted.');},'Delete supervisor',true);}break;
 case 'deactivate-instead':if(!requireOwner())return;{const s=sup(id);s.active=false;await save();closeModal();render();toast('Supervisor deactivated. Existing records retained.');}break;
 case 'prompt-now':await sendPrompt(id);break;case 'prompt-simulate':await sendPrompt(id,true);break;
 case 'upload-open':uploadForm(id);break;case 'choose-files':$('#upload-files')?.click();break;case 'take-photo':$('#camera-file')?.click();break;case 'sample-photos':addSamplePhotos();break;
 case 'upload-remove':pendingUploads=pendingUploads.filter(p=>p.id!==id);renderUploadThumbs();break;
 case 'photo-open':photoModal(id);break;case 'photo-clarify':clarificationForm(id);break;
 case 'generate-missing':await generateCaptions(reviewRows().filter(p=>p.status==='queued').map(p=>p.id));break;
 case 'regenerate':if(!requireOwner())return;{const ph=S.photos.find(p=>p.id===id);if(!ph)return;if(ph.caption.trim())confirmDialog('Replace this caption?','Regeneration replaces the current wording with a simulated draft and removes any prior approval. It does not analyse the image.',()=>generateCaptions([id]),'Regenerate draft');else await generateCaptions([id]);}break;
 case 'approve-one':await approvePhotos([id]);break;case 'approve-selected':approveConfirmation([...V.selected]);break;case 'approve-all':approveConfirmation(reviewRows().filter(p=>p.status==='review').map(p=>p.id));break;
 case 'request-changes':requestChanges(id);break;
 case 'report-tab':V.tab=b.dataset.tab;V.reportPage=0;render();break;
 case 'report-prev':V.reportPage--;await refreshReportPreview();break;case 'report-next':V.reportPage++;await refreshReportPreview();break;
 case 'report-export':await exportReport();break;
 case 'report-redownload':{const r=S.reports.find(r=>r.id===id);if(r)await exportReport(r);}break;
 case 'report-delete':if(!requireOwner())return;confirmDialog('Remove export history entry?','This removes the saved report snapshot from this browser. A PDF already downloaded to your device is not deleted.',async()=>{S.reports=S.reports.filter(r=>r.id!==id);await save();render();toast('Export history entry removed.');},'Remove entry',true);break;
 case 'inbox':changePage('inbox');break;
 case 'notifications-read':S.notifications.filter(n=>canAccess(project(n.project))&&(isOwner()||n.to===V.supervisor)).forEach(n=>n.read=true);await save();render();toast('Visible notifications marked as read.');break;
 case 'modal-close':closeModal();break;
 case 'confirm-action':{const fn=confirmCallback;closeModal();if(fn)await fn();}break;
 case 'help':helpModal();break;case 'install':await installApp();break;
 case 'reset-demo':confirmDialog('Reset the entire demo?','This permanently removes the local projects, uploaded photographs, custom supervisors, caption edits and report history, then restores the sample data. Downloaded PDF files are unaffected.',async()=>{S=makeSeed();V={role:'owner',supervisor:'s1',page:'overview',project:null,tab:'overview',query:'',filter:'all',reviewFilter:'pending',reviewProject:'all',selected:new Set(),reportProject:'p1',reportPage:0};await save();render();toast('Sample workspace restored.');},'Reset demo',true);break;
 }}catch(err){console.error(err);toast('That action could not be completed. Please try again.','error');}}
let searchTimer,reportTimer;
document.addEventListener('click',handleClick);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){V.query=el.value;const start=el.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const s=$('#search');s?.focus();s?.setSelectionRange(start,start);},180);}if(el.dataset.caption&&isOwner()){const ph=S.photos.find(p=>p.id===el.dataset.caption);if(!ph)return;const previous=ph.status;ph.caption=el.value;ph.status=ph.caption.trim()?'review':'queued';ph.approvedBy=null;ph.approvedAt=null;ph.revision++;V.selected.delete(ph.id);updateReviewCard(ph);scheduleSave();if(previous==='approved')toast('Caption changed. Owner approval must be renewed.');}if(el.dataset.uploadNote){const ph=pendingUploads.find(p=>p.id===el.dataset.uploadNote);if(ph)ph.note=el.value;}if(el.id?.startsWith('report-')&&el.id!=='report-project'){clearTimeout(reportTimer);reportTimer=setTimeout(refreshReportPreview,300);}});
document.addEventListener('change',async e=>{const el=e.target;switch(el.id){case 'identity':if(sup(el.value)?.active){V.supervisor=el.value;changePage('overview');}break;case 'project-filter':case 'photo-filter':case 'team-filter':V.filter=el.value;render();break;case 'review-project':V.reviewProject=el.value;V.selected.clear();render();break;case 'review-status':V.reviewFilter=el.value;V.selected.clear();render();break;case 'select-all':V.selected.clear();if(el.checked)reviewRows().filter(p=>p.status==='review').forEach(p=>V.selected.add(p.id));render();break;case 'f-cadence':$('#weekday-field')?.classList.toggle('hidden',el.value!=='weekly');$('#interval-field')?.classList.toggle('hidden',el.value!=='interval');break;case 'upload-files':case 'camera-file':await addFiles(el.files);el.value='';break;case 'report-project':V.reportProject=el.value;V.reportPage=0;render();break;}if(el.dataset.select){if(el.checked)V.selected.add(el.dataset.select);else V.selected.delete(el.dataset.select);const card=el.closest('.review-card');card?.classList.toggle('selected',el.checked);const count=$('#selected-count');if(count)count.textContent=`${V.selected.size} selected`;const btn=$('[data-act="approve-selected"]');if(btn)btn.disabled=V.selected.size===0;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['project-form','supervisor-form','task-form','upload-form','changes-form','clarify-form'].includes(form.id))return;e.preventDefault();try{if(form.id==='project-form')await saveProject(form);if(form.id==='supervisor-form')await saveSupervisor(form);if(form.id==='task-form')await saveTask(form);if(form.id==='upload-form')await submitUpload(form);if(form.id==='changes-form'){if(!requireOwner())return;const ph=S.photos.find(p=>p.id===form.dataset.id),reason=new FormData(form).get('reason').trim();if(!ph||!reason)return;ph.status='rejected';ph.rejection=reason;ph.approvedBy=null;ph.approvedAt=null;V.selected.delete(ph.id);S.notifications.push({id:uid('n'),project:ph.project,to:ph.supervisor,photo:ph.id,kind:'clarification',text:`Clarification requested for “${ph.title}”: ${reason}`,created:stamp(),read:false,fulfilled:false});addActivity('requested clarification on a photo caption.',ph.project);await save();closeModal();render();toast('Clarification request added to the supervisor inbox.');}if(form.id==='clarify-form'){const ph=S.photos.find(p=>p.id===form.dataset.id),note=new FormData(form).get('note').trim();if(!ph||!note||isOwner()||ph.supervisor!==V.supervisor||!canAccess(project(ph.project)))return;ph.note=note;ph.caption=draftCaption(ph);ph.status='review';ph.approvedAt=null;ph.approvedBy=null;ph.revision++;delete ph.rejection;S.notifications.forEach(n=>{if(n.kind==='clarification'&&n.photo===ph.id&&n.to===V.supervisor){n.fulfilled=true;n.read=true;}});addActivity('clarified a photo and resubmitted it for owner review.',ph.project);await save();closeModal();render();toast('Updated note and draft sent back for owner review.');}}catch(err){console.error(err);toast('The form could not be saved. Please try again.','error');}});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const els=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]):not([hidden]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('online',()=>toast('Connection restored. The demo still uses local device data.'));
window.addEventListener('offline',()=>toast('You are offline. Continue working with the locally cached demo.'));
window.addEventListener('pagehide',()=>{if(saveTimer){clearTimeout(saveTimer);save();}});
(async()=>{try{await initStore();render();if(!window.HNH_STANDALONE&&'serviceWorker'in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache unavailable',err));}}catch(e){console.error(e);$('#app').innerHTML='<main style="padding:40px"><h1>The workspace could not open</h1><p>Please reload this page in a current browser.</p></main>';}})();
